#pragma once
#include "ssd1306/ssd1306.h"
#include "UserInterfaceExtension.h"

// Text overlay position 
typedef enum {
    ANIM_TEXT_NONE,    // no overlay
    ANIM_TEXT_TOP,     // y = 0
    ANIM_TEXT_MIDDLE,  // y = (height - 8) / 2
    ANIM_TEXT_BOTTOM,  // y = height - 8
} anim_text_pos_t;

// Public API 
// Plays an animation centred on the display.
//
// frames        : flat byte array, row-major SSD1306 page format
// count         : number of frames
// frame_w       : pixel width of each frame
// frame_h       : pixel height of each frame
// delays        : per-frame delay in ms (from the generated header)
// speed_ms      : 0 = use per-frame delays from the header
//                 > 0 = override every frame with this fixed delay in ms
// scale         : rendered size relative to frame size (1.0 = full, 0.5 = half, 2.0 = double)
//                 nearest-neighbour; result is centred on the display
// overlay_text  : string drawn on every frame (NULL or "" = no text)
// text_pos      : ANIM_TEXT_TOP / MIDDLE / BOTTOM; text is centred horizontally,
//                 placed 2 px from the image/frame edge
void play_animation(ssd1306_t *poled,
                    const uint8_t  *frames,
                    int             count,
                    int             frame_w,
                    int             frame_h,
                    const uint16_t *delays,
                    int             speed_ms,
                    float           scale,
                    const char     *overlay_text,
                    anim_text_pos_t text_pos);

// Renders a static bitmap centred on the display.
//
// bitmap        : flat byte array in SSD1306 page format (from img_converter.py)
// img_w         : pixel width of the bitmap
// img_h         : pixel height of the bitmap
// scale / overlay_text / text_pos : same semantics as play_animation
void show_image(ssd1306_t      *poled,
                const uint8_t  *bitmap,
                int             img_w,
                int             img_h,
                float           scale,
                const char     *overlay_text,
                anim_text_pos_t text_pos);

